import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {releases,selectRelease,validateManifest,verifyBytes,checkDevice,checkOperation,downloadPart,prepare} from '../../ev-revival-local/integrity.mjs';
const r=releases[0],p=r.parts[0],bytes=fs.readFileSync('ev-revival-local/'+p.path);
const base='https://ev.jworldcreations.com/ev-revival-local/manifest.json';
const response=b=>async()=>({ok:true,arrayBuffer:async()=>b});
test('valid published binary and checksum',()=>verifyBytes(p,bytes));
test('modified firmware rejected',async()=>{const b=Buffer.from(bytes);b[100]^=1;await assert.rejects(verifyBytes(p,b),/SHA-256/)});
test('truncated download rejected',()=>assert.rejects(verifyBytes(p,bytes.subarray(0,-1)),/size/));
test('wrong checksum rejected',()=>assert.rejects(verifyBytes({...p,sha256:'0'.repeat(64)},bytes),/SHA-256/));
test('incorrect chip rejected',()=>assert.throws(()=>checkDevice(r,'ESP32-S3',4194304),/chip/));
test('incorrect or unknown flash capacity rejected',()=>{for(const n of [0,undefined,NaN,2097152,8388608])assert.throws(()=>checkDevice(r,'ESP32',n),/capacity/)});
test('missing manifest fields rejected',()=>{for(const k of Object.keys(r)){const m={...r};delete m[k];assert.throws(()=>validateManifest(m));}});
test('unexpected URLs and HTTP rejected',async()=>{await assert.rejects(downloadPart({...p,path:'https://evil.example/fw.bin'},base),/approved/);await assert.rejects(downloadPart(p,base.replace('https:','http:')),/HTTPS/)});
test('redirects disabled',async()=>{await downloadPart(p,base,async(u,o)=>{assert.equal(o.redirect,'error');return {ok:true,arrayBuffer:async()=>bytes}})});
test('interrupted download rejected',()=>assert.rejects(downloadPart(p,base,async()=>({ok:true,arrayBuffer:async()=>{throw Error('Interrupted')}})),/Interrupted/));
test('network failure rejected',()=>assert.rejects(downloadPart(p,base,async()=>{throw Error('Offline')}),/No erase or write/));
test('erase and data loss confirmation required',()=>{for(const mode of ['install','recovery']){assert.throws(()=>checkOperation(r,mode,false),/Confirm/);checkOperation(r,mode,true)}});
test('version selection accepts only approved release',()=>{assert.equal(selectRelease(r.version),r);assert.throws(()=>selectRelease('development'))});
test('settings-preserving update blocked even with consent',()=>assert.throws(()=>checkOperation(r,'update',true),/not validated/));
test('compatible connected device and verified download',async()=>{const b=await prepare(r,'ESP32',4194304,'recovery',true,base,response(bytes));assert.equal(b.length,1)});
test('incompatible device never downloads',async()=>{let fetched=false;await assert.rejects(prepare(r,'ESP8266',4194304,'install',true,base,()=>{fetched=true}));assert.equal(fetched,false)});
